} from '@ionic/react';
import { addOutline, createOutline, trashOutline, closeOutline, checkmark, chevronBack, chevronForward, personOutline } from 'ionicons/icons';
import Header from '../components/Header';
import AlertPopover from '../components/PopOver/AlertPopover';
import MailPopover from '../components/PopOver/MailPopover';
import { useUser } from '../contexts/UserContext';
import { getAllSuppliers, createSupplier, updateSupplier, deleteSupplier, Supplier } from '../api/supplierApi';
import { useIonViewWillEnter } from '@ionic/react';
import './SupplierPage.css';

const toHermosillo = (utc: string | undefined | null): string => {
  if (!utc) return '';
  const d = new Date(utc.includes('Z') ? utc : utc + 'Z');
  // Subtract 7 hours for UTC-7 (Hermosillo time)
  return new Date(d.getTime() - 7 * 60 * 60 * 1000).toLocaleString('es-MX', {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
  });
};

interface SupplierFormState {
  supplierName: string;
  contactName: string;
  phone: string;
  email: string;
  address: string;
  active: boolean;
}

const SupplierPage: React.FC = () => {
  const { companyId } = useUser();
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [loading, setLoading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isDeleteAlertOpen, setIsDeleteAlertOpen] = useState(false);
  const [selectedSupplier, setSelectedSupplier] = useState<Supplier | null>(null);
  const [formState, setFormState] = useState<SupplierFormState>({
    supplierName: '',
    contactName: '',
    phone: '',
    email: '',
    address: '',
    active: true,
  });
  const [formErrors, setFormErrors] = useState<Record<string, string>>({});

  const [page, setPage] = useState(0);
  const [pageSize] = useState(20);
  const [hasMore, setHasMore] = useState(true);

  const infiniteScrollRef = useRef<HTMLIonInfiniteScrollElement>(null);

  const [popoverState, setPopoverState] = useState<{ showAlertPopover: boolean; showMailPopover: boolean; event?: Event; }>(
    { showAlertPopover: false, showMailPopover: false }
  );

  const presentAlertPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showAlertPopover: true, event: e.nativeEvent });
  const dismissAlertPopover = () =>
    setPopoverState({ ...popoverState, showAlertPopover: false });
  const presentMailPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showMailPopover: true, event: e.nativeEvent });
  const dismissMailPopover = () =>
    setPopoverState({ ...popoverState, showMailPopover: false });

  const validateForm = () => {
    const errors: Record<string, string> = {};
    if (!formState.supplierName.trim()) {
      errors.supplierName = 'El nombre del proveedor es obligatorio.';
    }
    setFormErrors(errors);
    return Object.keys(errors).length === 0;
  };

  const loadSuppliers = async (reset = false) => {
    if (loading) return;
    setLoading(true);
    setError('');

    try {
      const fetchedSuppliers = await getAllSuppliers(companyId);
      // Implement client-side pagination since the backend `all_` endpoint doesn't support it directly.
      // For larger datasets, true server-side pagination would be needed.
      if (reset) {
        setSuppliers(fetchedSuppliers);
        setPage(1);
      } else {
        setSuppliers((prev) => [...prev, ...fetchedSuppliers.slice(page * pageSize, (page + 1) * pageSize)]);
        setPage((prev) => prev + 1);
      }
      setHasMore(suppliers.length + pageSize < fetchedSuppliers.length);
    } catch (err) {
      setError((err as Error).message ?? 'Error al cargar proveedores.');
    } finally {
      setLoading(false);
      if (infiniteScrollRef.current) {
        infiniteScrollRef.current.complete();
      }
    }
  };

  useIonViewWillEnter(() => {
    if (companyId) {
      loadSuppliers(true);
    }
  });

  useEffect(() => {
    if (companyId && suppliers.length === 0) {
      loadSuppliers(true);
    }
  }, [companyId]);

  const handleRefresh = async (event: CustomEvent<RefresherEventDetail>) => {
    await loadSuppliers(true);
    event.detail.complete();
  };

  const handleAddClick = () => {
    setSelectedSupplier(null);
    setFormState({
      supplierName: '',
      contactName: '',
      phone: '',
      email: '',
      address: '',
      active: true,
    });
    setFormErrors({});
    setIsModalOpen(true);
  };

  const handleEditClick = (supplier: Supplier) => {
    setSelectedSupplier(supplier);
    setFormState({
      supplierName: supplier.supplierName,
      contactName: supplier.contactName ?? '',
      phone: supplier.phone ?? '',
      email: supplier.email ?? '',
      address: supplier.address ?? '',
      active: supplier.active === '1',
    });
    setFormErrors({});
    setIsModalOpen(true);
  };

  const handleDeleteClick = (supplier: Supplier) => {
    setSelectedSupplier(supplier);
    setIsDeleteAlertOpen(true);
  };

  const handleSave = async () => {
    if (!validateForm()) {
      setError('Por favor, corrige los errores en el formulario.');
      return;
    }

    setIsSaving(true);
    try {
      if (selectedSupplier) {
        // Update existing supplier
        const updated = await updateSupplier(selectedSupplier.supplierId, {
          companyId: companyId,
          supplierName: formState.supplierName,
          contactName: formState.contactName || null,
          phone: formState.phone || null,
          email: formState.email || null,
          address: formState.address || null,
          active: formState.active ? '1' : '0',
        });
        setSuppliers(suppliers.map((s) => (s.supplierId === updated.supplierId ? { ...s, ...updated } : s)));
        setError('Proveedor actualizado exitosamente.');
      } else {
        // Create new supplier
        const newSupplier = await createSupplier({
          companyId: companyId,
          supplierName: formState.supplierName,
          contactName: formState.contactName || null,
          phone: formState.phone || null,
          email: formState.email || null,
          address: formState.address || null,
          active: formState.active ? '1' : '0',
        });
        setSuppliers([...suppliers, newSupplier]);
        setError('Proveedor creado exitosamente.');
      }
      setIsModalOpen(false);
      // Refresh the list to ensure all data is consistent after create/update.
      await loadSuppliers(true);
    } catch (err) {
      setError((err as Error).message ?? 'Error al guardar el proveedor.');
    } finally {
      setIsSaving(false);
    }
  };

  const confirmDelete = async () => {
    if (!selectedSupplier) return;

    setLoading(true);
    try {
      await deleteSupplier(selectedSupplier.supplierId, companyId);
      setSuppliers(suppliers.filter((s) => s.supplierId !== selectedSupplier.supplierId));
      setError('Proveedor eliminado exitosamente.');
    } catch (err) {
      setError((err as Error).message ?? 'Error al eliminar el proveedor.');
    } finally {
      setLoading(false);
      setSelectedSupplier(null);
    }
  };

  const loadMoreItems = (ev: CustomEvent<void>) => {
    if (hasMore) {
      loadSuppliers();
    } else {
      (ev.target as HTMLIonInfiniteScrollElement).complete();
    }
  };

  return (
    <IonPage className="supplier-page">
      <Header
        presentAlertPopover={presentAlertPopover}
        presentMailPopover={presentMailPopover}
        screenTitle="Proveedores — POS GMO"
      />
      <AlertPopover
        isOpen={popoverState.showAlertPopover}
        event={popoverState.event}
        onDidDismiss={dismissAlertPopover}
      />
      <MailPopover
        isOpen={popoverState.showMailPopover}
        event={popoverState.event}
        onDidDismiss={dismissMailPopover}
      />

      <IonContent fullscreen className="ion-padding">
        <IonRefresher slot="fixed" onIonRefresh={handleRefresh}>
          <IonRefresherContent pullingText="Pull to refresh" refreshingSpinner="crescent"></IonRefresherContent>
        </IonRefresher>

        {loading && suppliers.length === 0 && <IonLoading isOpen={loading} message="Cargando proveedores..." spinner="crescent" />}

        <IonList>
          {suppliers.map((supplier) => (
            <IonItem key={supplier.supplierId} className="supplier-item">
              <IonLabel>
                <h2>{supplier.supplierName}</h2>
                <p>{supplier.contactName} - {supplier.phone}</p>
                <p className={`supplier-status status-${supplier.active === '1' ? 'active' : 'inactive'}`}>
                  {supplier.active === '1' ? 'Activo' : 'Inactivo'}
                </p>
                <p>Email: {supplier.email}</p>
                <p>Dirección: {supplier.address}</p>
                <p className="supplier-date">Creado: {toHermosillo(supplier.created_At)}</p>
                {supplier.updated_at && <p className="supplier-date">Actualizado: {toHermosillo(supplier.updated_at)}</p>}
              </IonLabel>
              <IonButtons slot="end">
                <IonButton onClick={() => handleEditClick(supplier)} color="primary">
                  <IonIcon icon={createOutline} />
                </IonButton>
                <IonButton onClick={() => handleDeleteClick(supplier)} color="danger">
                  <IonIcon icon={trashOutline} />
                </IonButton>
              </IonButtons>
            </IonItem>
          ))}
        </IonList>

        <IonInfiniteScroll onIonInfinite={loadMoreItems} threshold="100px" disabled={!hasMore || loading} ref={infiniteScrollRef}>
          <IonInfiniteScrollContent loadingSpinner="crescent" loadingText="Cargando más proveedores..."></IonInfiniteScrollContent>
        </IonInfiniteScroll>

        {!loading && suppliers.length === 0 && (
          <div className="ion-text-center ion-padding-top">
            <p>No hay proveedores registrados. ¡Añade uno!</p>
          </div>
        )}

        <IonFab vertical="bottom" horizontal="end" slot="fixed">
          <IonFabButton onClick={handleAddClick}>
            <IonIcon icon={addOutline} />
          </IonFabButton>
        </IonFab>

        <IonModal isOpen={isModalOpen} onDidDismiss={() => setIsModalOpen(false)} className="supplier-modal">
          <IonHeader>
            <IonToolbar>
              <IonTitle>{selectedSupplier ? 'Editar Proveedor' : 'Añadir Proveedor'}</IonTitle>
              <IonButtons slot="end">
                <IonButton onClick={() => setIsModalOpen(false)}>
                  <IonIcon icon={closeOutline} />
                </IonButton>
              </IonButtons>
            </IonToolbar>
          </IonHeader>
          <IonContent className="ion-padding">
            <div className="form-field-group">
              <IonInput
                fill="outline"
                label="Nombre del Proveedor *"
                labelPlacement="floating"
                value={formState.supplierName}
                onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState({ ...formState, supplierName: e.detail.value as string })}
                className={formErrors.supplierName ? 'ion-invalid ion-touched' : ''}
                errorText={formErrors.supplierName}
              />
            </div>

            <div className="form-field-group">
              <IonInput
                fill="outline"
                label="Nombre de Contacto"
                labelPlacement="floating"
                value={formState.contactName}
                onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState({ ...formState, contactName: e.detail.value as string })}
              />
            </div>

            <div className="form-field-group">
              <IonInput
                fill="outline"
                label="Teléfono"
                labelPlacement="floating"
                value={formState.phone}
                onIonInput={(e: CustomEvent<InputInputEventDetail>) => setFormState({ ...formState, phone: e.detail.value as string })}
                type="tel"
              />
            </div>

            <div className="form-field-group">
              <IonInput
                fill="outline"
                label="Email"
                labelPlacement="floating"
                value={formState.email}
